  const cell2 = Math.sin(sx*0.22-t*0.3)*Math.cos(sy*0.18+t*0.2)*0.4;
  const cellBlend = Math.tanh((cell+cell2)*1.5)*0.3;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((act*0.5 + harmonic*0.8 - inh*0.4 + spiral*0.5)*1.8);
  const rd3 = Math.tanh((rd1*0.6 + rd2*0.4 + cellBlend*0.3)*2.0);
  const edge = Math.abs(rd3-rd2)+Math.abs(rd2-rd1);
  const edgeMask = Math.tanh(edge*8);
  const blend = rd3*0.65 + cellBlend*0.2 + edgeMask*0.15, v = blend*0.5+0.5;
  const pal = [[5,15,55],[10,45,85],[15,85,110],[25,140,130],[80,170,120],[180,190,80],[220,175,60],[215,130,70],[195,90,75],[165,55,70],[120,30,60],[60,18,50],[5,15,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(rd3*Math.PI)*0.15, edgeBright = 1.0+edgeMask*0.25, shimmer = 0.95+Math.sin(harmonic*Math.PI*2)*0.05;
