    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edgeBright*shimmer)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edgeBright*shimmer)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edgeBright*shimmer)|0
  ];
}
